head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[ModelUtil > M > isRunningWorkflow]<br/>실행 중인 Workflow 가 있는지 여부를 반환합니다.",
    "validation" : [
        "workflowId(선택) 파라미터로 특정 Workflow 의 실행 여부를 확인할 수 있어야 합니다.",
        "workflowId(선택) 파라미터 생략 시 전체 Workflow 중 실행 중인 것이 있는지 확인해야 합니다.",
        "실행 중이면 true, 아니면 false 를 반환해야 합니다.",
        "반환값은 Boolean 타입이어야 합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// workflow step 의 마지막 function - 실행 진행 구간에서 isRunningWorkflow 호출 확인
scwin.wf_function_last = function () {
    var isRun = WebSquare.ModelUtil.isRunningWorkflow();
    wf_body_bottom.getObj("scwin").setReturnValue("[step] function - WebSquare.ModelUtil.isRunningWorkflow() → 반환 타입 : " + (typeof isRun) + " / 값 : " + isRun);
};

// submission pre - 실행 진행 구간에서 WebSquare.ModelUtil.isRunningWorkflow() 호출 확인
scwin.sbm_exam1_pre = function (submissionId, workflowObj) {
    var scenario = par_scenario.getValue();

    if (scenario === "1") {
        // 시나리오 1 : workflowId 파라미터 생략 → 실행 중 workflow 유무 확인
        var isRun = WebSquare.ModelUtil.isRunningWorkflow();
        wf_body_bottom.getObj("scwin").setReturnValue("[pre] WebSquare.ModelUtil.isRunningWorkflow() (ID 생략) → 반환 타입 : " + (typeof isRun) + " / 값 : " + isRun);
    } else if (scenario === "2") {
        // 시나리오 2 : workflowId 파라미터 지정 → 해당 ID 의 workflow 실행 여부 확인
        var isRun1 = WebSquare.ModelUtil.isRunningWorkflow("wf_exam1");
        wf_body_bottom.getObj("scwin").setReturnValue("[pre] WebSquare.ModelUtil.isRunningWorkflow('wf_exam1') → 반환 타입 : " + (typeof isRun1) + " / 값 : " + isRun1);

        // 존재하지 않는 workflow ID 조회 → false
        var isRun2 = WebSquare.ModelUtil.isRunningWorkflow("wf_not_exists");
        wf_body_bottom.getObj("scwin").setReturnValue("[pre] WebSquare.ModelUtil.isRunningWorkflow('wf_not_exists') → 반환 타입 : " + (typeof isRun2) + " / 값 : " + isRun2);
    }

    return true;
};

// workflow 전체 콜백
scwin.wf_resolveCallback = function (wObj) {
    wf_body_bottom.getObj("scwin").setReturnValue("[resolveCallback] workflow 완료");
};

scwin.wf_rejectCallback = function (wObj) {
    wf_body_bottom.getObj("scwin").setReturnValue("[rejectCallback] workflow 오류");
};



scwin.btn_isRunningWorkflow_onclick = function () {
    var scenario = par_scenario.getValue();

    if (scenario === "1") {
        // 시나리오 1 : workflowId 파라미터 생략 - 실행 중 workflow 유무 확인 (true)
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 1 : WebSquare.ModelUtil.isRunningWorkflow() (ID 생략) - 실행 중 Workflow 있으면 true 반환 ──");
        WebSquare.ModelUtil.executeWorkflow("wf_exam1");
    } else if (scenario === "2") {
        // 시나리오 2 : workflowId 파라미터 지정 - 특정 Workflow 실행 여부 확인
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 2 : WebSquare.ModelUtil.isRunningWorkflow('wf_exam1') / WebSquare.ModelUtil.isRunningWorkflow('wf_not_exists') - 특정 ID 실행 여부 확인 ──");
        WebSquare.ModelUtil.executeWorkflow("wf_exam1");
    } else if (scenario === "3") {
        // 시나리오 3 : 실행 중 workflow 가 없을 때 → false 반환
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 3 : 실행 중 Workflow 가 없을 때 호출 - false 반환 ──");
        var isRun = WebSquare.ModelUtil.isRunningWorkflow();
        wf_body_bottom.getObj("scwin").setReturnValue("btn onclick 구간 WebSquare.ModelUtil.isRunningWorkflow() → 반환 타입 : " + (typeof isRun) + " / 값 : " + isRun + " (실행 중 workflow 없음)");

        // 특정 ID 조회도 false
        var isRunById = WebSquare.ModelUtil.isRunningWorkflow("wf_exam1");
        wf_body_bottom.getObj("scwin").setReturnValue("btn onclick 구간 WebSquare.ModelUtil.isRunningWorkflow('wf_exam1') → 반환 타입 : " + (typeof isRunById) + " / 값 : " + isRunById);
    }
};
